{
  "actions": [
    {
      "action": "Offer a transparent draft-review starting point",
      "mechanism": "A named starting point exposes its exact permission changes instead of concealing an undocumented preset.",
      "implementation": "Add an optional “Review drafts” choice with a readable permission list. Apply it only after confirmation; retain access to all 18 toggles.",
      "check": "Verify applying it enables draft review but not publishing or billing; canceling leaves every toggle unchanged.",
      "risk": "A misleading label could conceal excessive access; validate effective permissions."
    },
    {
      "action": "Require deliberate selection of privileged access",
      "mechanism": "Publishing and billing cannot become granted merely through choosing a preset or copying another teammate.",
      "implementation": "Require separate, initially unchecked owner selections for publishing and billing. Surface any calculated indirect grant and its controlling settings for explicit selection.",
      "check": "Exercise every preset and copy path; neither privilege may become effective without the corresponding owner selection.",
      "risk": "Do not remove privileged combinations; make them explicitly selectable."
    },
    {
      "action": "Show effective access before sending",
      "mechanism": "A live capability summary translates toggle combinations into concrete outcomes, including dependencies that change effective access.",
      "implementation": "Calculate permissions after edits. Show “Can review drafts,” “Cannot publish,” and billing access, with links to controlling settings and explanations of indirect grants.",
      "check": "Compare summary statements against calculated permissions across dependency-heavy combinations; stale or failed calculations must not appear current.",
      "risk": "Simplified wording must not omit scope restrictions or conditional access."
    },
    {
      "action": "Preserve custom combinations as first-class configurations",
      "mechanism": "Preset labels describe exact matches; they never overwrite permissions simply because a configuration resembles a preset.",
      "implementation": "Load existing combinations unchanged, label nonmatches “Custom,” and switch edited presets to “Custom.” Require confirmation before any explicit replacement.",
      "check": "Round-trip all stored custom configurations without permission changes; verify opening, editing, and canceling preset selection never silently normalizes them.",
      "risk": "Renaming or updating presets must not migrate existing custom configurations."
    },
    {
      "action": "Test the invitee’s intended limits before sending",
      "mechanism": "Scenario assertions catch unintended effective privileges rather than merely checking the visible toggle positions.",
      "implementation": "For the draft-review task, run preflight assertions: draft review allowed, publishing denied, billing denied. On failure, return the owner to the implicated settings.",
      "check": "Seed a fixture with publishing inherited through another setting; assert the test fails and no invitation is sent.",
      "risk": "For other legitimate tasks, owners must explicitly revise expectations."
    },
    {
      "action": "Organize controls for complete keyboard operation",
      "mechanism": "Semantic groups and predictable focus make detailed permission editing manageable without hiding less-common combinations.",
      "implementation": "Group all toggles by task using native fieldsets and checkboxes. Provide keyboard-operable disclosure controls, visible focus, and focus links from summary warnings.",
      "check": "Using only a keyboard, create a custom combination, inspect effective access, resolve a warning, and send; verify no traps or inaccessible controls.",
      "risk": "Collapsed groups can conceal selected permissions; display their selection counts."
    },
    {
      "action": "Make permission changes visible and reversible",
      "mechanism": "An explicit difference view reveals what a preset or bulk edit would add and remove.",
      "implementation": "Before applying replacements, list added and removed effective capabilities, emphasizing publishing and billing. Offer cancel and an undo that restores the previous draft configuration.",
      "check": "Replace a custom combination, inspect the difference, then undo; assert all 18 values return exactly to their previous state.",
      "risk": "Undo must also invalidate obsolete privilege confirmations and preflight results."
    },
    {
      "action": "Bind sending to the configuration actually checked",
      "mechanism": "A versioned draft prevents a successful preview or test from authorizing a subsequently edited invitation.",
      "implementation": "Associate calculations, assertions, and owner selections with a permission-draft revision. Invalidate them after relevant edits; send only the exact validated payload through the existing invite flow.",
      "check": "Edit permissions while calculation is pending, then attempt sending; stale results must not enable submission or supply its payload.",
      "risk": "This prevents UI staleness, not authorization-backend races."
    }
  ],
  "abstention_reason": ""
}
